{
  "narratives": [
    {
      "item_code": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "start": "p2:L6",
      "end": "p2:L8"
    },
    {
      "item_code": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "start": "p2:L9",
      "end": "p2:L13"
    },
    {
      "item_code": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "start": "p2:L14",
      "end": "p2:L18"
    },
    {
      "item_code": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "start": "p2:L19",
      "end": "p2:L21"
    },
    {
      "item_code": "S4_DOCTOR",
      "title_raw": "마. 응급처치 및 의사의 주의사항",
      "start": "p2:L22",
      "end": "p2:L23"
    }
  ],
  "extras": [
    {
      "after_item": "S4_EYE",
      "title_raw": "가. 눈에 들어갔을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "물질과 접촉시 즉시 20분 이상 흐르는 물에 눈을 씻어내시오.",
          "line": "p2:L7"
        },
        {
          "value": "즉시 의료조치를 취하시오.",
          "line": "p2:L8"
        }
      ],
      "line": "p2:L6"
    },
    {
      "after_item": "S4_SKIN",
      "title_raw": "나. 피부에 접촉했을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "물질과 접촉시 즉시 20분 이상 흐르는 물에 피부를 씻어내시오",
          "line": "p2:L10"
        },
        {
          "value": "오염된 옷과 신발을 제거하고 격리하시오.",
          "line": "p2:L11"
        },
        {
          "value": "재사용 전에는 옷과 신발을 완전히 씻어내시오.",
          "line": "p2:L12"
        },
        {
          "value": "즉시 의료조치를 취하시오.",
          "line": "p2:L13"
        }
      ],
      "line": "p2:L9"
    },
    {
      "after_item": "S4_INHAL",
      "title_raw": "다. 흡입했을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "긴급 의료조치를 받으시오",
          "line": "p2:L15"
        },
        {
          "value": "신선한 공기가 있는 곳으로 옮기시오",
          "line": "p2:L16"
        },
        {
          "value": "호흡하지 않는 경우 인공호흡을 실시하시오",
          "line": "p2:L17"
        },
        {
          "value": "호흡이 힘들 경우 산소를 공급하시오",
          "line": "p2:L18"
        }
      ],
      "line": "p2:L14"
    },
    {
      "after_item": "S4_INGEST",
      "title_raw": "라. 먹었을 때",
      "reason": "코드없음",
      "statements": [
        {
          "value": "의식이 없는 사람에게 입으로 아무것도 먹이지 마시오.",
          "line": "p2:L20"
        },
        {
          "value": "즉시 의료조치를 취하시오.",
          "line": "p2:L21"
        }
      ],
      "line": "p2:L19"
    },
    {
      "after_item": "S4_DOCTOR",
      "title_raw": "마. 응급처치 및 의사의 주의사항",
      "reason": "코드없음",
      "statements": [
        {
          "value": "의료인력이 해당물질에 대해 인지하고 보호조치를 취하도록 하시오.",
          "line": "p2:L23"
        }
      ],
      "line": "p2:L22"
    }
  ]
}

